/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    scwin.changeHeader(grd_Grid1);
    scwin.changeHeader(grd_Grid2);
    scwin.changeHeader(grd_Grid3);
    scwin.changeHeader(grd_Grid4);
    scwin.changeHeader(grd_Grid5);
    scwin.changeHeader(grd_Grid6);
    url += "&TYPE=1";
    url += "&SCREN_ID=" + "ULDSTF26800.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid1",
        action : "/DisclosureCountStatistics.do",
        ref : "",
        target : "dts_Grid1=body.content",
        isProcessMsg : false
    };

