/**
 * @method
 * @name changeHeader
 * @description change Header 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.changeHeader = function(obj) {
    const clientnow = new Date();
    const curYear = "" + clientnow.getYear();
    const curMonth = "" + ((clientnow.getMonth()) + 1);
    const NOW_MONTH = curYear.substring(2, 4) + "." + curMonth;
    const ONE_YEAR = (curYear.substring(2, 4) - 1);
    const TWO_YEAR = (curYear.substring(2, 4) - 2);
    let THREE_YEAR = "" + (curYear.substring(2, 4) - 3);
    if (THREE_YEAR.length === 1) {
        THREE_YEAR = "0" + THREE_YEAR;
    }
    let FOUR_YEAR = "" + (curYear.substring(2, 4) - 4);
    if (FOUR_YEAR.length === 1) {
        FOUR_YEAR = "0" + FOUR_YEAR;
    }
    let FIVE_YEAR = "" + (curYear.substring(2, 4) - 5);
    if (FIVE_YEAR.length === 1) {
        FIVE_YEAR = "0" + FIVE_YEAR;
    }
    obj.setColumnProp('NOW_MONTH', 'Name', "`" + NOW_MONTH + "월");
    obj.setColumnProp('ONE_YEAR', 'Name', "`" + ONE_YEAR);
    obj.setColumnProp('TWO_YEAR', 'Name', "`" + TWO_YEAR);
    obj.setColumnProp('THREE_YEAR', 'Name', "`" + THREE_YEAR);
    obj.setColumnProp('FOUR_YEAR', 'Name', "`" + FOUR_YEAR);
    obj.setColumnProp('FIVE_YEAR', 'Name', "`" + FIVE_YEAR);
};
